nta.declaration:
const double F = 0.1;           // frequency, unit: second

const int X = 0;
const int Y = 1;
const int Z = 2;
const int D = 2;                // dimensions: 1-x; 2-x,y; 3-x,y,z

clock tp[D], tv[D];
double ta[D];

clock ep[D], ev[D];
double ea[D];

/*
 tranformation between double and int
*/
const uint8_t BASE = 10;
const uint8_t EXPONENT = 1;
int32_t d2i(const double value) {
    return fint(value*pow(BASE,EXPONENT));
}
double i2d(const int32_t value) {
    return value/pow(BASE,EXPONENT);
}

/** Shielding */
import "/home/rong/Github/AutoScene/car/shield/logic_scenario.so"
{
    bool is_action_ok(double tpx, double tpy, double tvx, double tvy, double tax, double tay,
                    double epx, double epy, double evx, double evy, double eax, double eay);
    void get_action(double tpx, double tpy, double tvx, double tvy, double &tax, double &tay,
                    double epx, double epy, double evx, double evy, double eax, double eay,
                    double P, double AMINX, double AMINY, double AMAXX, double AMAXY, 
                    double VMINX, double VMINY, double VMAXX, double VMAXY, int& waypoint);
    void initialize(clock &tpx, clock &tpy, clock &epx, clock &epy);
};

void begin(){
    initialize(tp[X],tp[Y],ep[X],ep[Y]);
    tv[X] = 0.1;
    ev[X] = 0.1;
}

bool shield(int tax, int tay){
    double d_tax = i2d(tax);
    double d_tay = i2d(tay);

    //return is_action_ok(tp[X],tp[Y],tv[X],tv[Y],d_tax,d_tay,ep[X],ep[Y],ev[X],ev[Y],ea[X],ea[Y]);
    return true;
}

int waypoint = 0;
void get_acce(const int32_t AMIN[D], const int32_t AMAX[D], 
              const int32_t VMIN[D], const int32_t VMAX[D]){
    get_action(tp[X],tp[Y],tv[X],tv[Y],ta[X],ta[Y],
                       ep[X],ep[Y],ev[X],ev[Y],ea[X],ea[Y], F,
                       i2d(AMIN[X]), i2d(AMIN[Y]), i2d(AMAX[X]), i2d(AMAX[Y]),
                       i2d(VMIN[X]), i2d(VMIN[Y]), i2d(VMAX[X]), i2d(VMAX[Y]), waypoint);
}

nta.system:
clock time;

const int32_t AMAX[D] = {d2i(1.0), d2i(1.0)};
const int32_t AMIN[D] = {d2i(-1.0), d2i(-1.0)};
const int32_t VMAX[D] = {d2i(9.0), d2i(9.0)};
const int32_t VMIN[D] = {d2i(-5.0), d2i(-5.0)};
test = Kinematics(tp,tv,ta);
control = Controller(AMAX, AMIN, VMAX, VMIN);
ego = Kinematics(ep,ev,ea);
// List one or more processes to be composed into a system.
system ego, test, control;
